# kind: V (code, start, end) | P (code, dur) | G (code, dur)
def t(s):
    m,sec=s.split(':'); return int(m)*60+float(sec)
R=[]
def V(ch,vo,text,code,a,b,desc,claim): R.append(dict(ch=ch,vo=vo,text=text,kind='V',code=code,a=t(a),b=t(b),desc=desc,claim=claim))
def P(ch,vo,text,code,d,desc,claim): R.append(dict(ch=ch,vo=vo,text=text,kind='P',code=code,d=d,desc=desc,claim=claim))
def G(ch,vo,text,code,d,desc,claim): R.append(dict(ch=ch,vo=vo,text=text,kind='G',code=code,d=d,desc=desc,claim=claim))
H='Hook'; C1='1. A gun for walking'; C2='2. Machine gun by default'; C3='3. One gun, twelve men'; C4='4. Built around the BAR'; C5='5. The price'; C6='6. Korea: the mainstay'; C7='7. Verdict'
# ---- HOOK
V(H,'VO01',"[serious] By 1944, every Marine rifle squad was built around one weapon, carried three times over.",'V02','2:20.874','2:26.947',"two Marines walk forward through smoke on Peleliu, one carrying his weapon low, D-Day, 15 September 1944; SEQUENCE A",'C01; C33')
V(H,'VO01',"[short pause] It was designed in 1917 for another war: to be fired from the hip while walking toward the enemy.",'V01','9:18.617','9:26.617',"1925 Army training film: soldier walks toward the camera across an open field firing the BAR from the hip (\"marching fire\"); SEQUENCE A",'C02')
V(H,'VO01',"Twenty rounds in the magazine. At full speed, about two seconds of fire.",'V01','9:01.533','9:07.533',"same film: automatic hip firing, dust kicked up downrange; SEQUENCE A",'C03; C14')
V(H,'VO01',"It weighed about twenty pounds, and its barrel could not be changed when it overheated.",'V03','9:22.448','9:28.448',"Marines run in a line past an amphibious tractor on Peleliu (Fury in the Pacific, 1945); SEQUENCE A",'C04; C05')
V(H,'VO01',"Yet in Korea, soldiers called it indispensable, and could not imagine fighting without it.",'V04','2:19.206','2:26.547',"two U.S. soldiers fire from cover on a Korean hillside, summer 1951 (Combat Bulletin No. 113); SEQUENCE A",'C06')
V(H,'VO01',"[pause] This is how a walking gun became the weapon an entire squad was built around.",'V03','8:15.897','8:22.897',"Marines move through shattered brush and coral on Peleliu; SEQUENCE A",'N/A')
# ---- CH1
V(C1,'VO02',"[measured] When America went to war in 1917, its troops in France were issued French automatic weapons, like the Chauchat.",'V05','0:13.080','0:22.080',"column of U.S. infantry marches along a road in France, autumn 1918 (92nd Division film; context for the AEF)",'C07')
V(C1,'VO02',"The French had a doctrine for them. Attacking infantry carried automatic rifles forward and fired as they walked,",'V05','1:17.311','1:26.286',"U.S. soldiers among shattered trees in the Meuse-Argonne sector, 1918",'C07')
V(C1,'VO02',"keeping the enemy's heads down until the line reached his trench. [short pause] It was called walking fire.",'V05','1:26.286','1:32.292',"close shot: helmeted U.S. soldiers move past a tree trunk, 1918",'C07')
P(C1,'VO02',"John Browning, the country's best-known gun designer, built a better weapon for that job in 1917. His son Val, seen here in 1918, would later demonstrate it against the Germans himself.",'P01',12.0,"Val A. Browning holding an M1918 BAR, 1918; slow push-in from the full figure to the rifle's receiver and magazine",'C02; C08')
V(C1,'VO02',"It was gas-operated. A little gas from each shot was tapped off the barrel. It drove back a piston, and the piston was connected to the slide that worked the action.",'V01','5:06.000','5:19.400',"1925 training-film animation: gas passes down the port and pushes the piston and slide rearward; period on-screen captions (\"SOME OF THE GAS PASSES DOWN HERE\", \"AND PUSHES BACK THIS PISTON\", \"WHICH IS CONNECTED TO THE SLIDE\") stay visible",'C09')
V(C1,'VO02',"Moving back, the slide compressed a spring. The spring then drove it forward again to load the next round.",'V01','5:30.000','5:37.000',"same animation: slide moves rearward and compresses the recoil spring (caption \"...AND SLIDE MOVE REARWARD THEY COMPRESS A SPRING\")",'C09')
V(C1,'VO02',"The result was the M1918: a full-power rifle cartridge, a twenty-round box magazine, and about sixteen pounds of weight. Light enough for one man to carry in an assault.",'V01','7:30.000','7:41.800',"animation ends on the magazine spring, then the film's clean side-profile drawing of the complete M1918",'C10')
V(C1,'VO02',"A lever on the left chose semi-automatic, automatic, or safe.",'V01','7:52.900','7:58.900',"close-up: a hand moves the change lever past the F, A and S markings",'C10')
V(C1,'VO02',"Production started in 1918, but General Pershing held the new rifle back, so the Germans would not capture one too early. [short pause] The 79th Division finally took it into action in September 1918. It was used widely in the Meuse-Argonne offensive, the largest American offensive of the war.",'V05','0:46.580','1:04.580',"U.S. troops move through wrecked woodland toward the front, Meuse-Argonne, autumn 1918",'C11')
V(C1,'VO02',"The Marines wanted it too. Men of the 6th Marines talked Army troops into a trade: their Chauchats for BARs.",'V05','1:09.970','1:17.311',"close view along a trench wall as U.S. soldiers move through it, 1918",'C35')
V(C1,'VO02',"[short pause] On October 9, 1918, an order came down. Every Browning in Marine hands was to be turned in.",'V05','2:14.034','2:23.277',"U.S. soldiers gather at an iron gate behind the line, autumn 1918",'C35')
V(C1,'VO02',"By the armistice in November, fifty-two thousand had been built. [short pause] It came too late to change the war. But the Army had found a weapon it would keep for the next forty years.",'V05','1:32.292','1:46.292',"U.S. infantry in brush and trees close behind the line, 1918",'C12; C30')
# ---- CH2
V(C2,'VO03',"[thoughtful] Between the wars, Army training films still taught it as a rifle. On automatic, standing, it emptied its magazine in one long burst.",'V01','8:20.000','8:29.900',"1925 film: soldier raises the BAR and fires standing on automatic; dust erupts around the target row; soldier lowers the gun",'C13')
G(C2,'VO03',"The numbers explain why that mattered. At about five hundred and fifty rounds a minute, twenty rounds last a little over two seconds. [short pause] The Army's own manual put the most effective rate at only a hundred and twenty to a hundred and fifty rounds a minute.",'G01',19.0,"show the magazine-versus-time data and exact labels listed in G01",'C03; C14')
V(C2,'VO03',"As a new war came closer, the Army faced an awkward fact: it had no portable light machine gun for its rifle squads.",'V01','9:34.800','9:44.000',"1925 film: soldier fires prone from a sandbag rest; insert of the target with a tight group; back to the firer",'C15')
V(C2,'VO03',"So on June 30, 1938, it turned the BAR into one. The new M1918A2 got a bipod near the muzzle, and a mechanism in the stock to slow its rate of fire.",'V01','9:46.300','9:59.900',"close-up of the prone firer behind the sandbag, then a low side view along the barrel",'C15')
V(C2,'VO03',"It lost its semi-automatic setting, and now fired only on full automatic, at a fast or a slow rate. [short pause] With its sling, it weighed about twenty pounds.",'V01','11:06.550','11:18.550',"1925 film: a soldier with the BAR slung demonstrates the stoppage drill with a hand-held instruction card",'C04; C15')
V(C2,'VO03',"And it got a new job. When the Army entered the Second World War, the BAR was the only automatic weapon in its twelve-man rifle squad.",'V07','11:14.641','11:28.641',"U.S. infantrymen advance through smoke and olive trees, Italy, December 1943 (The Battle of San Pietro, 1945; CONTEXT: partly reconstructed scenes)",'C16; C34')
# ---- CH3
V(C3,'VO04',"[measured] On paper, the squad had a leader, an assistant leader, seven riflemen,",'V07','12:13.333','12:19.006',"U.S. soldiers clamber over rocks on a hillside, Italy (San Pietro film; CONTEXT)",'C16; C34')
V(C3,'VO04',"and one three-man automatic rifle team, built around the BAR:",'V07','12:32.452','12:37.191',"soldiers move up between boulders under smoke (San Pietro film; CONTEXT)",'C16; C34')
P(C3,'VO04',"a gunner, an assistant who carried more magazines and could take over, and an ammunition bearer. [short pause] Here, a BAR team of the 325th Regiment fires on advancing Germans in December 1944.",'P02',12.0,"BAR team in a firing position behind a hedgerow bank, Company C, 325th Regiment, 23 December 1944; slow push toward the gunner; keep the period negative number visible, it is part of the record",'C16; C17')
V(C3,'VO04',"In the Army's plan, the riflemen were the attack.",'V07','12:37.191','12:41.161',"a soldier walks forward into battle smoke (San Pietro film; CONTEXT)",'C18; C34')
V(C3,'VO04',"The BAR supported them as a base of fire, pinning the enemy down while the riflemen moved forward.",'V07','14:38.278','14:48.422',"soldiers on a rocky slope as a shell bursts above them (San Pietro film; CONTEXT)",'C18; C34')
V(C3,'VO04',"In combat, units bent the rules. Some ran one-man BAR teams, with every rifleman carrying spare magazines.",'V08','0:54.000','1:01.100',"U.S. infantryman runs across a cobbled street, Bochum, Germany, 12 April 1945",'C19')
V(C3,'VO04',"Many Army divisions put two BAR teams in each squad, so one could keep firing while the other reloaded.",'V08','1:01.261','1:10.500',"U.S. infantry with packs move along a town street, Bochum, April 1945",'C19')
V(C3,'VO04',"They were copying an idea that had come out of the Pacific, [short pause] where the Marine Corps had gone much further and rebuilt its whole squad around the gun.",'V08','1:10.571','1:21.800',"a U.S. soldier watches the street from a window with his weapon ready, Bochum, April 1945",'C19')
# ---- CH4
V(C4,'VO05',"[curious] In early 1944, the Marines reorganized their rifle squads. A squad of thirteen was split into three fire teams of four, and every one of those teams was built around a BAR.",'V06','0:47.648','1:01.962',"Marines of the 6th Marine Division advance in open order across a field, Okinawa, 1945",'C01; C32')
G(C4,'VO05',"[firm] Compare the two. The Army squad had one BAR supporting eleven other men. [short pause] The Marine squad had three. Each team had a corporal in command, a rifleman, an assistant automatic rifleman, and the automatic rifleman himself. The riflemen were there to protect and feed the gun.",'G02',22.0,"show the two squad diagrams and exact labels listed in G02",'C01; C16; C18')
V(C4,'VO05',"On paper, a Marine rifle company now carried twenty-seven BARs, and a regiment two hundred and forty-three. Across a division, the count rose from about five hundred in 1943 to more than eight hundred and sixty by 1945.",'V02','3:28.408','3:41.588',"three consecutive shots: Marines advance in open order across the Peleliu airfield, 15 September 1944",'C20; C33')
P(C4,'VO05',"In the jungle, BAR men often walked near the head or the tail of a patrol, where a sudden burst could break an ambush on a narrow trail. This Marine on Cape Gloucester, in January 1944, carries his ready to fire.",'P03',15.0,"Marine with BAR at the ready in dense jungle, Cape Gloucester, New Britain, January 1944; crop inside the print border so the handwritten notes and archive number are off frame; slow tilt from the BAR up to his face",'C21')
V(C4,'VO05',"Many Marines threw the bipod away to save weight.",'V03','8:44.172','8:48.966',"Marines with packs walk away from camera through the Peleliu scrub",'C21')
V(C4,'VO05',"In many ways, the BAR went back to what Browning had first designed:",'V03','9:10.172','9:15.655',"Marines fire from behind shattered trees, Peleliu",'C21')
V(C4,'VO05',"an automatic rifle carried by one man, fired from the shoulder or the hip, moving with the riflemen around it.",'V03','9:45.207','9:53.207',"wide view: a lone Marine crosses open ground with his weapon, Peleliu",'C21')
V(C4,'VO05',"On Okinawa in 1945, the 6th Marine Division fought through ridges like these with fire teams built around the BAR.",'V06','0:22.122','0:33.600',"a Marine climbs a brush-covered slope, Okinawa, 1945",'C01; C32')
P(C4,'VO05',"[short pause] For the Marines, the BAR was no longer just a support weapon. It was the center of the team.",'P04',12.0,"kneeling Marine fires a BAR through brush, 1944; slow push-in along the barrel; NO SFX",'C01')
# ---- CH5
V(C5,'VO06',"[serious] That center came at a price, and the BAR man paid it.",'V02','2:10.964','2:17.504',"a heavily loaded Marine walks forward through smoke on Peleliu",'C04')
G(C5,'VO06',"With its sling, the gun alone weighed about twenty pounds, more than twice an M1 rifle. Each loaded magazine added almost a pound and a half. [short pause] In Korea, a gunner's belt held twelve of them, and many carried three or four more in their pockets.",'G03',20.0,"show the weight comparison and exact labels listed in G03",'C04; C22; C23')
V(C5,'VO06',"And it was not a simple gun. A 1925 training film walks soldiers through its stoppages and its small, breakable parts.",'V01','10:52.633','11:03.250',"1925 film: extractor, firing pin and connector laid out on a grid, each identified by a hand-held card",'C13')
V(C5,'VO06',"The barrel was screwed into the receiver. It could not be swapped out when it grew hot in a long fight.",'V01','10:37.467','10:46.800',"1925 film: soldier draws back the operating handle and removes the magazine",'C05')
V(C5,'VO06',"Real light machine guns, like the British Bren, could change barrels in the field.",'V03','7:15.034','7:21.034',"a Marine crouches behind cover beside stacked ammunition, Peleliu",'C25')
P(C5,'VO06',"[measured] It also needed constant care. The rate reducer in the stock was a delicate spring-and-weight system. One ordnance sergeant called it a Rube Goldberg device.",'P05',12.0,"Sgt. Leonard Zajas, 8th Infantry Division, cleans his BAR during a rest period in Germany, December 1944; slow push from his face to the open action",'C24')
V(C5,'VO06',"In the humid Pacific, its gas cylinder, never made of stainless steel, could rust solid unless it was cleaned every day.",'V06','3:55.836','4:03.343',"Marines in tall vegetation, Okinawa, 1945",'C24')
V(C5,'VO06',"Kept clean, it was rugged and reliable.",'V02','2:30.851','2:35.122',"a Marine in a foxhole under a log on Peleliu",'C24')
V(C5,'VO06',"But the next war would test it harder.",'V03','7:27.207','7:31.552',"close: two Marines' helmets at the edge of cover, Peleliu",'N/A')
# ---- CH6
V(C6,'VO07',"[somber] In Korea, the BAR went to war a third time. Many were old weapons rebuilt in Japan, and in the hard winter of 1950, some of them failed.",'V09','3:28.300','3:44.300',"Marines and a jeep on a frozen road below the mountains around the Chosin Reservoir, 10 December 1950",'C26')
V(C6,'VO07',"One Army battalion, the 2nd of the 38th Infantry, lost faith in its BARs after the fighting near Kunu-ri. [short pause] When the failures were checked, almost every gun that had quit was a reconditioned one, cleaned but left with its old springs.",'V10','13:37.583','13:53.583',"two U.S. soldiers climb a steep Korean hillside, early 1951 (Combat Bulletin No. 108)",'C26')
V(C6,'VO07',"New guns, straight from the factory, had almost no trouble at all.",'V04','1:53.413','1:59.553',"U.S. soldiers move up through brush on a Korean slope, summer 1951",'C26')
V(C6,'VO07',"The man who recorded this was the military historian S. L. A. Marshall.",'V04','2:40.093','2:45.432',"a U.S. machine-gun team fires from a Korean hillside position, 1951",'C27')
G(C6,'VO07',"[firm] In 1951 he interviewed infantrymen across Eighth Army for an Army research office. His conclusion was blunt. The BAR, even more than the machine gun, was the fire base the whole fight was built around. One BAR man, he wrote, could quiet a sniper-infested area better than five or six riflemen.",'G04',22.0,"show Marshall's findings and exact labels listed in G04",'C27')
V(C6,'VO07',"Wherever the rifle line began to bend, he found, commanders sent the BARs to hold it.",'V04','1:21.415','1:27.087',"wide view of a terraced Korean hillside where U.S. infantry are deployed, 1951",'C27')
V(C6,'VO07',"Riflemen were willing to carry extra ammunition for it.",'V04','1:39.600','1:44.605',"a U.S. soldier advances across a terraced field, Korea, 1951",'C27')
V(C6,'VO07',"His verdict: the BAR in Korea merits a clean bill.",'V04','1:27.087','1:30.991',"U.S. soldiers in thick brush on a Korean slope, 1951",'C26')
V(C6,'VO07',"And he passed on what the troops asked for: double the number of BARs.",'V10','10:26.583','10:32.333',"U.S. soldiers fire from a wooded ridge, Korea, early 1951",'C27')
G(C6,'VO07',"[measured] The numbers show how long America leaned on it. About a hundred and two thousand were built for the First World War. [short pause] More than a hundred and eighty-eight thousand new ones came in the Second, on top of older guns rebuilt. During Korea, the Royal typewriter company built sixty-one thousand more.",'G05',22.0,"show the production figures and exact labels listed in G05",'C29')
V(C6,'VO07',"A young soldier who fought there, David Hackworth, later called it the best weapon of the Korean War.",'V09','2:13.767','2:20.400',"Marines wave from a truck during the move south from the Chosin Reservoir, December 1950",'C28')
# ---- CH7
G(C7,'VO08',"[reflective] By the 1950s, the BAR was more than thirty years old. The Army began replacing it with an automatic version of the M14 rifle, and from 1957 with the belt-fed M60 machine gun. [short pause] Its story runs in a straight line: a walking gun in 1918, a squad machine gun in 1938, the heart of the Marine fire team in 1944.",'G06',24.0,"show the timeline and exact labels listed in G06",'C02; C15; C01; C30')
V(C7,'VO08',"So was it a good light machine gun? No.",'V02','4:50.991','4:54.795',"two Marines run across the foreground of the Peleliu airfield",'N/A')
V(C7,'VO08',"Its magazine was too small, and its barrel was fixed.",'V02','5:08.642','5:13.000',"silhouette: Marines advance beside a tank across the Peleliu airfield",'C03; C05')
V(C7,'VO08',"But that was never really its job.",'V06','4:07.748','4:11.618',"a Marine runs forward through the brush, Okinawa, 1945",'N/A')
V(C7,'VO08',"It was an automatic rifle that one man could carry anywhere a rifleman could go.",'V10','11:38.083','11:43.800',"U.S. soldiers walk across a snowy riverbank, Korea, early 1951",'N/A')
P(C7,'VO08',"[pause] In 2010, the Marine Corps chose a new weapon for the automatic riflemen in its fire teams: the M27, a light, magazine-fed automatic rifle, picked to replace a belt-fed machine gun.",'P06',13.0,"U.S. Marine fires an M27 Infantry Automatic Rifle during a squad competition, Northern Territory, Australia, 23 May 2013; slow push-in",'C31')
V(C7,'VO08',"The idea John Browning built in 1917, one man carrying the fire of a machine gun, had come back.",'V02','3:48.562','3:56.370',"a Marine crouches and moves forward close to camera on Peleliu",'C31')
V(C7,'VO08',"[reflective] It had been built to walk. In the end, a whole squad walked around it.",'V05','2:03.524','2:14.034',"OUTRO: U.S. skirmish line advances across an open field, autumn 1918; NARRATION ENDS AT 11:14.3; VISUAL HOLD UNTIL 11:19.3; picture fades to black over the last 5 seconds; music swells slightly then fades",'C02')
